widgets_values:
{
  "整体风格": "3D CG古风玄幻动漫，Q版萌系与唯美东方仙侠结合，轻松搞笑又温馨治愈，充满奇幻童趣与东方美学，破败魔界的冷白幽暗与修仙界的明亮温暖形成强烈对比，空气里浮着魔界灰雾与修仙界七彩灵光微粒",
  "角色档案": [
    "扶频，女，三岁幼童模样魔界小公主，乌黑软发扎成双丫髻系朱红丝带，粉雕玉琢圆脸大眼睛长睫毛，穿暗红绣暗金魔纹小襦裙裙摆及膝，足蹬朱红小绣鞋，肩挎黑布小包袱",
    "扶萧，男，魔君，俊美邪魅成年男子，墨色长发半披半束以墨玉冠固定，额间一枚暗色菱形魔纹，穿玄色绣暗金龙纹宽袖长袍袖口微有磨损，腰系暗金玉带，足蹬黑纹长靴，气质邪魅却带着落魄感",
    "扶燕，男，少年模样魔界大王子，墨发束成高马尾以黑布带系，面容俊朗带慵懒笑意，穿黑色打补丁劲装腰系粗布带，腰间别一柄锈迹斑斑短剑，脚上皮靴鞋头快磨出洞",
    "独眼老魔，男，老年魔人守卫，花白须发杂乱，左眼戴黑色牛皮眼罩，右眼神色浑浊，脸上一道斜跨旧疤，穿锈迹斑斑旧铠甲，手持铁长矛",
    "无名修士，男，青年修士，青色道袍束发戴白玉冠，面容清俊，周身环绕金色防护罩灵光，背后背一柄桃木剑",
    "羊角摆渡人，男，魔人摆渡者，头顶一对弯曲黑色羊角，皮肤偏深褐，面容粗犷却眼神温和，穿灰褐粗布短打，赤足撑竹篙"
  ],
  "道具档案": [
    "魔界通行令，黑乎乎玄铁令牌巴掌大小，正面刻着扭曲魔界符文泛着暗紫光，背面刻一行小字如有遗失恕不补办魔界财务部宣，边缘有磕碰磨损痕迹，表面有细微划痕",
    "家书，泛黄糙纸折成简陋信封，封面上歪歪扭扭写着亲亲媳妇收五个墨字字迹潦草如蚯蚓爬，封口用面糊随意粘住边缘翘边，纸张薄而透能隐约看见里面字迹",
    "下品灵石，三块灰扑扑拳头大矿石，表面有淡得几乎看不见的灵气纹路，色泽暗淡无光，质地粗糙凹凸不平，散发微弱灵气波动，边角圆润似被把玩过",
    "幽冥铁玄矿，最低品阶黑色矿石拳头大小，表面粗糙凹凸不平，有微弱暗金属光泽，沉甸甸的，边缘有敲击凿打的痕迹"
  ],
  "场景档案": [
    "魔宫主殿，主光源是穹顶残存夜明珠发出的冷白色微光，光线昏暗不均明暗交界线分明，地面是黑色大理石铺就但布满裂纹缝隙长着零星苔藓，四围矗立八根高大黑色石柱柱身有风化痕迹和斑驳纹路，殿中央摆一张裂了三条缝的黑色石质王座一条腿松动垫着碎石，殿门口两侧各有一尊石狮子左侧那尊轮廓模糊是炭笔描的，穹顶有几处破洞能看见外面阴沉夜空，远处墙角堆着杂物，整体破败萧条充满落魄感",
    "幽冥裂缝，主光源是两侧岩壁发出的幽绿色磷光，光线诡异幽暗忽明忽暗，地面是黑色碎石子和灰渣踩上去沙沙响，两侧是高耸近乎垂直的黑色岩壁爬满发光苔藓纹路诡异，空中飘浮着若隐若现的黑影，空气中弥漫淡淡的灰黑色雾气能见度低，岩壁缝隙里偶尔闪过红色光点，阴森诡异充满危险感",
    "黑风谷，主光源是昏黄色天光从谷顶缝隙洒下，光线浑浊昏黄被沙尘稀释，地面是黄沙混合碎石被风蚀出波纹，两侧是陡峭黄褐色岩壁被风蚀出沟壑纹路，空中飞沙走石狂风卷起沙尘形成一道道风柱，岩壁上挂着被风吹得猎猎作响的枯草，荒凉萧瑟风声呼啸震耳欲聋",
    "忘川支流河岸，主光源是河面上飘荡的幽蓝色鬼火，光线阴冷幽蓝摇曳不定，河岸是黑色泥土地踩上去陷脚印，河水呈暗黄色浑浊状水面有波纹泛着诡异光，岸边停着一艘破旧小木船船板有裂缝用麻绳补着，船板上放着一根竹篙，远处河面雾气朦胧看不清对岸，岸边散落着几块碎石，阴森神秘",
    "修仙界边界山林，主光源是温暖金色阳光透过树叶缝隙洒下，光线明亮柔和形成斑驳光影，地面是翠绿青草点缀五颜六色野花，四周是郁郁葱葱参天古木树叶翠绿欲滴，树枝上挂着藤蔓和花朵，远处是连绵青山轮廓云雾缭绕，空气中有淡淡的七彩灵气光晕，远处传来鸟鸣声，生机盎然充满希望感"
  ],
  "分镜序列": [
    {
      "编号": 1,
      "标题": "魔宫主殿-王座上的小公主",
      "时间段": [
        "0-3s，极缓推大全景转中全景。冷白色夜明珠微光从穹顶稀疏洒下明暗交界线分明，破败魔宫主殿中央裂了三条缝的黑色石质王座上，扶频盘腿坐在正中小身子陷在宽大王座里，两只小短腿悬空晃啊晃，暗红小襦裙裙摆及膝，双丫髻朱红丝带垂落，肩挎黑布小包袱，八根风化石柱矗立四周，穹顶破洞漏进阴沉夜空，音效：空旷大殿回声，远处水滴声",
        "3-15s，微移近景。冷白微光打在扶频粉雕玉琢圆脸上，她眉头皱着，小手撑着腮帮子，一脸严肃地盯着前方，长睫毛忽闪忽闪，小嘴巴抿成一条线，大眼睛在微光下亮晶晶，内心OS：“我叫扶频，魔君之女。可今天我爹却养不起我了，要把我送出去打秋风。”音效：衣料摩擦的轻响"
      ]
    },
    {
      "编号": 2,
      "标题": "魔宫主殿-扶频的辩解",
      "时间段": [
        "0-8s，微移中近景。冷白微光下扶频坐在黑色石质王座上身体前倾，两只小手在空中比划着，大眼睛认真看着前方，小嘴巴一张一合一脸我很讲道理的表情，长睫毛随说话微动，暗红小襦裙暗金魔纹在微光下隐约反光，扶频说：\"爹，我昨天就吃了两碗糊糊、一个幽冥果、半块风干肉而已！\"（口音：稚嫩女童音，语速：中，情绪：认真辩解），音效：小手挥动的风声"
      ]
    },
    {
      "编号": 3,
      "标题": "魔宫主殿-扶萧卖惨开场",
      "时间段": [
        "0-5s，极缓推近景。冷白微光从侧面打在扶萧俊美邪魅的脸上，他蹲在王座前与扶频平视，深邃眼眸注视着扶频，俊脸上闪过一丝心虚，嘴角勉强扯出温柔的笑，一只手搭在王座扶手上手指不自觉摩挲，墨色长发半披半束，额间暗色菱形魔纹在微光下若隐若现，扶萧说：\"频儿啊，不是爹不想养你。\"（口音：低沉磁性男音，语速：慢，情绪：心虚温柔），音效：衣料摩擦声",
        "5-10s，微移中景。冷白微光下扶萧缓缓站起身，身形高大却微微佝偻，双手摊开一脸无奈，头微微偏向一侧不敢直视扶频，玄色长袍袖口在微光下泛着磨损毛边，暗金龙纹随动作晃动，扶萧说：\"可咱之前攻打修仙界打输了，赔款赔得裤衩都快当了。\"（口音：低沉磁性男音，语速：中，情绪：尴尬无奈），音效：长袍拖地的窸窣声"
      ]
    },
    {
      "编号": 4,
      "标题": "魔宫主殿-石狮子都跑了",
      "时间段": [
        "0-8s，跟随中全景转全景。冷白微光中扶萧转身走向殿门口，玄色绣暗金龙纹长袍随步伐摆动，墨色长发半披半束，边走边抬手指向门口方向，额间暗色菱形魔纹微动，镜头跟随手势移动，殿门口两尊石狮子逐渐进入画面，黑色大理石地面裂纹清晰，八根石柱隐在暗处，扶萧说：\"现在魔界是真的穷啊，穷得连魔宫门口的看门石狮子上个月都跑了一只。\"（口音：低沉磁性男音，语速：中，情绪：痛心疾首），音效：脚步声在空旷大殿回响"
      ]
    },
    {
      "编号": 5,
      "标题": "魔宫主殿-炭笔描的石狮子",
      "时间段": [
        "0-6s，焦点转移特写到中景。冷白微光下殿门口左侧石狮子占据画面，轮廓模糊不清线条歪歪扭扭，明显是用炭笔在墙上草草描出来的，炭笔痕迹还能看到笔触和涂抹痕迹，右侧石狮子则是真实黑色石雕鬃毛分明神态威严，与左侧炭笔画形成鲜明对比，殿门口黑色石柱和裂纹地面在背景中，音效：风吹过门缝的呜咽声"
      ]
    },
    {
      "编号": 6,
      "标题": "魔宫主殿-王座接雨水",
      "时间段": [
        "0-8s，升降中全景转仰拍全景。冷白微光中扶萧站在裂了三条缝的黑色石质王座旁，抬起右手指向穹顶方向，头微微仰起，玄色长袍下摆垂地，墨色长发半披半束，镜头顺着手指方向缓缓上升，穹顶破洞和稀疏夜明珠逐渐展现，大部分夜明珠位置是空的凹槽，几处破洞漏进阴沉月光，穹顶石壁有水渍痕迹，八根黑色石柱顶部风化斑驳，扶萧说：\"你看这魔宫，上次下雨，还是我拿王座接的水。\"（口音：低沉磁性男音，语速：慢，情绪：惨兮兮），音效：远处隐约的雷声"
      ]
    },
    {
      "编号": 7,
      "标题": "魔宫主殿-夜明珠少了",
      "时间段": [
        "0-6s，仰拍大全景。冷白色微光从穹顶洒下，穹顶上稀稀拉拉嵌着几颗夜明珠发出微弱冷光，大部分位置都是空的凹槽清晰可见，几处破洞漏进外面阴沉的月光，夜明珠的光忽明忽暗，穹顶石壁上有明显水渍痕迹和风化纹路，八根高大黑色石柱顶部隐在微光中，整体破败萧条，音效：水滴从破洞滴落的声音"
      ]
    },
    {
      "编号": 8,
      "标题": "魔宫主殿-哥哥去挖矿",
      "时间段": [
        "0-8s，横移中全景。冷白微光下扶萧的手指从穹顶方向转向殿门口，镜头顺着方向横移，殿门口扶燕进入画面，他少年模样墨发束成高马尾以黑布带系，面容俊朗带慵懒笑意，穿黑色打补丁劲装腰系粗布带，腰间别一柄锈迹斑斑短剑，懒洋洋靠在门框上，补丁在微光下格外显眼，脚上皮靴鞋头快磨出洞，扶萧说：\"你再看你哥，一百零八岁了，还得天天带队去挖矿，补贴家用。\"（口音：低沉磁性男音，语速：中，情绪：无奈又心疼），音效：轻微的哈欠声"
      ]
    },
    {
      "编号": 9,
      "标题": "魔宫主殿-落魄扶燕",
      "时间段": [
        "0-7s，微移中景。冷白微光从侧面打在扶燕身上，他靠在魔宫殿门口门框上，一只手插在腰间，另一只手捂着嘴打哈欠，墨发高马尾有些凌乱碎发垂落，黑色劲装上好几处补丁清晰可见，腰间锈迹斑斑短剑随动作轻晃，脚上靴子鞋头磨损严重快磨出洞，整个人透着慵懒落魄感，冷白夜明珠微光在脸上形成明暗交界，音效：哈欠声，靴子蹭地面的声音"
      ]
    },
    {
      "编号": 10,
      "标题": "魔宫主殿-扶燕拆台",
      "时间段": [
        "0-10s，微移中近景。冷白微光下扶燕直起身，双手抱胸靠在门框上，头微微歪着，嘴角勾起一抹慵懒的笑，眼神里带着调侃，墨发高马尾随动作微微晃动，黑色补丁劲装衣角微微扬起，腰间锈迹斑斑短剑别在腰侧，背景是魔宫主殿内部模糊轮廓，扶燕说：\"爹，你就直说咱们养不起妹妹了，想把她送到娘那儿打秋风。铺垫那么多干嘛。\"（口音：少年清冽音，语速：中快，情绪：慵懒调侃），音效：衣料摩擦声"
      ]
    },
    {
      "编号": 11,
      "标题": "魔宫主殿-亲情探访",
      "时间段": [
        "0-6s，微移近景。冷白微光下扶萧猛地转头瞪向扶燕方向，眼睛瞪大眉毛竖起，手指着门口方向，俊脸上写满你怎么拆台的气急败坏，额间暗色菱形魔纹微微发亮，墨色长发随转头动作甩动，玄色长袍袖子挥动，背景是魔宫主殿黑色石柱和裂纹地面，扶萧说：\"闭嘴！什么叫打秋风？这叫……亲情探访！\"（口音：低沉磁性男音，语速：快，情绪：气急败坏），音效：衣袖挥动的风声"
      ]
    },
    {
      "编号": 12,
      "标题": "魔宫主殿-忽悠频儿",
      "时间段": [
        "0-4s，极缓推近景。冷白微光下扶萧迅速转向扶频，努力挤出慈祥的笑容嘴角弧度有些僵硬，蹲下身与扶频平视，一只手轻轻放在扶频头顶，眼神努力变得温柔，墨色长发半披半束，额间魔纹微光闪烁，扶萧说：\"频儿，你听爹说。\"（口音：低沉磁性男音，语速：慢，情绪：努力慈祥），音效：衣料摩擦声",
        "4-8s，微移中近景。冷白微光中扶萧眼睛突然变得亮晶晶，身体微微前倾，双手比划着，脸上洋溢向往神情，长发随动作滑落肩头，额间魔纹若隐若现，玄色长袍暗金龙纹随动作晃动，扶萧说：\"你娘现在是清云宗宗主，修仙界有名的大富婆……啊不是，是大能！\"（口音：低沉磁性男音，语速：中快，情绪：激动向往），音效：手势挥动的风声",
        "8-12s，手势加强近景。冷白微光下扶萧越说越激动，双手大幅度挥舞，眼睛里闪着光，嘴角咧得大大的完全忘了装慈祥，整个人像在推销好东西，长袍袖子甩来甩去，墨色长发散乱肩头，扶萧说：\"灵石多得能填平咱们魔界的熔岩河。\"（口音：低沉磁性男音，语速：快，情绪：亢奋），音效：兴奋的呼吸声"
      ]
    },
    {
      "编号": 13,
      "标题": "魔宫主殿-美好生活画饼",
      "时间段": [
        "0-10s，微移近景。冷白微光下扶萧掰着手指头数，一根一根地掰，修长手指在微光下清晰可见，脸上带着陶醉向往神情，头微微仰起仿佛已经看到美好画面，嘴角口水都快流下来，长睫毛在眼下投出阴影，墨色长发半披半束垂在肩头，玄色长袍暗金龙纹在微光下隐约反光，扶萧说：\"你去她那儿，顿顿有灵米吃，天天有灵果啃，穿的是云锦法衣，睡的是暖玉床……\"（口音：低沉磁性男音，语速：中慢，情绪：陶醉向往），音效：掰手指的轻响"
      ]
    },
    {
      "编号": 14,
